world.workers.forEach((w,i)=>{drawPerson(w.x,w.y,w.color,Math.atan2(w.ty-w.y,w.tx-w.x),'worker',i*3);if(distance(w,player)<95){ctx.font='9px system-ui';ctx.textAlign='center';ctx.fillStyle='#d6e8ed';ctx.fillText(w.role,w.x,w.y-24);ctx.textAlign='left'}});
