if(stage===0){world.plane.x-=28*dt;world.plane.arrive-=dt*.12;if(world.plane.x<=680){world.plane.x=680;world.plane.arrive=0;stepStage(1);say('Aeronave estacionada. Asegura el tren delantero.')}}
// autonomous crew walking and workflow
world.workers.forEach((w,i)=>{w.phase+=dt;if(stage===1&&i===1){w.tx=world.plane.x-100;w.ty=world.plane.y+56;if(distance(w,{x:w.tx,y:w.ty})<12&&!world.chocks){world.chocks=true;stepStage(2);say('La cuadrilla colocó calzos. Posiciona las escaleras.')}}else if(stage===2&&i===3&&!world.stairs.placed){w.tx=world.stairs.x;w.ty=world.stairs.y;if(distance(w,{x:w.tx,y:w.ty})<16){world.stairs.placed=true;say('El operador posicionó y estabilizó la escalera.');stepStage(3)}}else if(stage>=3&&stage<=5){w.tx=stage===3?world.belt.x:stage===5?world.plane.x-60:470;w.ty=stage===3?world.belt.y+25:stage===5?world.plane.y+55:495}else{w.tx=355+(i%3)*28;w.ty=435+Math.floor(i/3)*22}movePerson(w,dt,38+(i%2)*8)});
// apron vehicles roll in rather than appearing
