// conveyor physically advances each case to carts
if(world.belt.on){const b=world.bags.find(q=>q.state==='hold');if(b){b.state='belt';b.x=world.plane.x-10;b.y=world.plane.y+58;b.moveT=0}const moving=world.bags.find(q=>q.state==='belt');if(moving){moving.moveT=(moving.moveT||0)+dt;const t=clamp(moving.moveT/1.6,0,1);moving.x=(world.plane.x-10)+(world.belt.x-world.plane.x+10)*t;moving.y=(world.plane.y+58)+(world.carts[0].y-world.plane.y-58)*t;if(t>=1){moving.state='cart';moving.x=world.carts[0].x+rnd(-14,14);moving.y=world.carts[0].y+rnd(-7,7);world.unloaded++;refreshTask()}}}
// autonomous loading, one suitcase physically moves from cart toward cargo hatch
if(stage===5&&world.loaded<flight.manifest){let b=world.bags.find(q=>q.state==='cart'&&!q.aiLoad);if(b){b.aiLoad=true;b.state='loading';b.moveT=0}b=world.bags.find(q=>q.state==='loading');if(b){b.moveT+=dt*.32;const t=clamp(b.moveT,0,1);b.x=world.carts[1].x+(world.plane.x-70-world.carts[1].x)*t;b.y=world.carts[1].y+(world.plane.y+56-world.carts[1].y)*t;if(t>=1){b.state='loaded';world.loaded++;refreshTask()}}}
// passenger routes, individual pacing
world.pax.forEach((p,i)=>{if(p.wait>0){p.wait-=dt;return}if(p.state==='deplane'){if(movePerson(p,dt,45)){p.state='claim';p.tx=520+(i%6)*17;p.ty=620+Math.floor(i/6)*16}}else if(p.state==='claim'){p.wait=rnd(1,3);if(Math.random()<.35){p.state='gone';p.tx=230;p.ty=410}}else if(p.state==='board'){if(movePerson(p,dt,37)){p.state='onboard';world.boarding++}}else if(p.state==='assist'){if(movePerson(p,dt,27)){p.state='assisted';world.assistDone=true}}});
// assistance workers make actual trip to passenger
if(stage===4&&!world.assistDone){const p=world.pax.find(q=>q.assist&&q.state!=='assisted');if(p){p.state='assist';p.tx=world.stairs.x+38;p.ty=world.stairs.y+82;const w=world.workers[4];w.tx=p.x;w.ty=p.y;if(distance(w,p)<13){p.state='assisted';p.tx=270;p.ty=350;world.assistDone=true;say('Agente y silla de asistencia acompañan al pasajero.') }}}
// arrivals and pushback physical movement, rotation, taxi and lift-off
if(world.depart>0){world.depart+=dt*.07;world.plane.x+=dt*22;world.plane.y+=dt*7;world.plane.angle=Math.min(.14,world.plane.angle+dt*.02);if(world.depart>5&&completionTimer===0){completionTimer=1;finishFlight()}}
