 function activeTarget(){const targets=[];const add=(name,x,y,fn,range=48)=>targets.push({name,x,y,fn,range});
 if(stage===1&&!world.chocks)add('Colocar calzos',world.plane.x-100,world.plane.y+60,()=>{world.chocks=true;world.workers[1].tx=world.plane.x-100;world.workers[1].ty=world.plane.y+48;say('Calzos colocados. Aeronave asegurada.');stepStage(2)});
 if(stage===2&&!world.stairs.placed)add('Posicionar escalera',world.stairs.x,world.stairs.y,()=>{world.stairs.placed=true;say('Escalera estabilizada. Pasajeros desembarcando.');world.pax.forEach((p,i)=>{p.state='deplane';p.tx=380+(i%5)*16;p.ty=500+Math.floor(i/5)*17});stepStage(3)});
 if(stage===2&&world.stairs.placed)add('Abrir bodega',world.plane.x-6,world.plane.y+42,()=>{world.door=1;stepStage(3);say('Bodega abierta. Lleva la cinta a la puerta de carga.')});
-if(stage===3&&world.door<1)add('Abrir bodega',world.plane.x-6,world.plane.y+42,()=>{world.door=1;say('Bodega abierta.');});
+if(stage===3&&world.door<1)add('Abrir bodega',world.plane.x-100,world.plane.y+50,()=>{world.door=1;say('Bodega abierta.');});
+if(stage===3&&world.door>0&&world.unloaded===0)add('Activar descarga',world.belt.x,world.belt.y,()=>{if(world.belt.placed){world.belt.on=true;say('Cinta activa. Descarga en curso.')}else say('Primero acerca la cinta transportadora.')});
 if(stage===3&&!world.belt.placed)add('Acercar cinta',world.belt.x,world.belt.y,()=>{world.belt.placed=true;world.tractor.parked=false;world.tractor.x=430;world.tractor.y=530;world.carts.forEach((c,i)=>{c.x=490+i*28;c.y=505+i*20});say('Cinta y carritos en posición. Pulsa USAR para arrancar.');});
